insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m1-1', 'lesson:m1', 'm1', 'mudah', 'mcq', 'konsep', 'Manakah yang merupakan persamaan linear dua variabel?', '{"options":[{"id":"a","text":"x² + y = 9"},{"id":"b","text":"3x − 4y = 12"},{"id":"c","text":"2x + 7 = 15"},{"id":"d","text":"xy = 6"}],"context":null,"pairLabels":null,"hints":["Periksa pangkat setiap variabel.","PLDV harus memiliki dua variabel berbeda."]}'::jsonb, 'b', '["3x − 4y = 12 memuat dua variabel (x dan y) yang masing-masing berpangkat satu.","x² + y = 9 memuat pangkat dua, 2x + 7 = 15 hanya satu variabel, dan xy = 6 berisi perkalian dua variabel."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m1-2', 'lesson:m1', 'm1', 'mudah', 'number', 'konsep', 'Berapakah koefisien y pada persamaan 7x − 5y = 30? (Tulis lengkap dengan tandanya.)', '{"options":null,"context":null,"pairLabels":null,"hints":["Koefisien adalah bilangan di depan variabel.","Jangan lupakan tanda minus."]}'::jsonb, '-5', '["Suku yang memuat y adalah −5y.","Bilangan di depan y beserta tandanya adalah −5."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m1-3', 'lesson:m1', 'm1', 'mudah', 'tf', 'penyelesaian', 'Pasangan (2, 3) merupakan penyelesaian dari 3x + 2y = 12.', '{"options":null,"context":null,"pairLabels":null,"hints":["Ganti x dengan 2 dan y dengan 3."]}'::jsonb, 'true', '["Substitusikan x = 2 dan y = 3: 3(2) + 2(3) = 6 + 6 = 12.","Hasilnya sama dengan ruas kanan, jadi pernyataan benar."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m1-4', 'lesson:m1', 'm1', 'sedang', 'number', 'penyelesaian', 'Jika x = 4 pada persamaan x + 2y = 10, berapakah nilai y?', '{"options":null,"context":null,"pairLabels":null,"hints":["Ganti x dengan 4 terlebih dahulu.","Pindahkan 4 ke ruas kanan, lalu bagi dengan 2."]}'::jsonb, '3', '["4 + 2y = 10","2y = 10 − 4 = 6","y = 6 : 2 = 3"]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m2-1', 'lesson:m2', 'm2', 'mudah', 'mcq', 'penyelesaian', 'Pasangan manakah yang merupakan penyelesaian dari x + y = 9 dan x − y = 3?', '{"options":[{"id":"a","text":"(6, 3)"},{"id":"b","text":"(5, 4)"},{"id":"c","text":"(3, 6)"},{"id":"d","text":"(7, 2)"}],"context":null,"pairLabels":null,"hints":["Semua pilihan memenuhi x + y = 9. Uji persamaan kedua."]}'::jsonb, 'a', '["Uji (6, 3): 6 + 3 = 9 ✓ dan 6 − 3 = 3 ✓.","Pasangan lain hanya memenuhi persamaan pertama."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m2-2', 'lesson:m2', 'm2', 'mudah', 'tf', 'konsep', 'SPLDV selalu memiliki tepat satu penyelesaian.', '{"options":null,"context":null,"pairLabels":null,"hints":["Ingat tiga kemungkinan posisi dua garis."]}'::jsonb, 'false', '["Tidak selalu. Jika kedua garis sejajar, tidak ada penyelesaian.","Jika kedua garis berimpit, penyelesaiannya tak hingga."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m2-3', 'lesson:m2', 'm2', 'mudah', 'mcq', 'konsep', 'Berapa banyak penyelesaian dari satu persamaan x + y = 4 jika x dan y bilangan real?', '{"options":[{"id":"a","text":"Tidak ada"},{"id":"b","text":"Tepat satu"},{"id":"c","text":"Tepat dua"},{"id":"d","text":"Tak hingga banyaknya"}],"context":null,"pairLabels":null,"hints":["Coba x = 0, x = 1, x = 2,... apakah selalu ada y yang cocok?"]}'::jsonb, 'd', '["Setiap nilai x yang dipilih menghasilkan satu nilai y yang sesuai.","Karena pilihan x tak terbatas, penyelesaiannya tak hingga."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m2-4', 'lesson:m2', 'm2', 'sedang', 'tf', 'konsep', 'Jika grafik dua persamaan dalam SPLDV sejajar, maka SPLDV tersebut tidak memiliki penyelesaian.', '{"options":null,"context":null,"pairLabels":null,"hints":["Penyelesaian SPLDV = titik potong."]}'::jsonb, 'true', '["Garis sejajar tidak pernah berpotongan.","Tanpa titik potong, tidak ada pasangan yang memenuhi kedua persamaan."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m3-1', 'lesson:m3', 'm3', 'mudah', 'mcq', 'model', 'Harga 3 apel dan 2 jeruk Rp13.000, sedangkan harga 1 apel dan 1 jeruk Rp5.000. Jika a = harga 1 apel dan j = harga 1 jeruk, model yang tepat adalah ...', '{"options":[{"id":"a","text":"3a + 2j = 13.000 dan a + j = 5.000"},{"id":"b","text":"3a + 2j = 5.000 dan a + j = 13.000"},{"id":"c","text":"2a + 3j = 13.000 dan a + j = 5.000"},{"id":"d","text":"3a × 2j = 13.000 dan a + j = 5.000"}],"context":null,"pairLabels":null,"hints":["Bilangan di depan nama buah menjadi koefisien.","Cocokkan setiap nota dengan harganya."]}'::jsonb, 'a', '["\"3 apel dan 2 jeruk\" berarti 3a + 2j, harganya 13.000.","\"1 apel dan 1 jeruk\" berarti a + j, harganya 5.000."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m3-2', 'lesson:m3', 'm3', 'mudah', 'mcq', 'konsep', 'Langkah pertama dalam membuat model matematika dari soal cerita adalah ...', '{"options":[{"id":"a","text":"Langsung mengeliminasi variabel"},{"id":"b","text":"Mengidentifikasi informasi yang diketahui dan ditanyakan"},{"id":"c","text":"Menebak jawaban akhir"},{"id":"d","text":"Menggambar grafik"}],"context":null,"pairLabels":null,"hints":["Apa yang perlu kamu pahami sebelum menulis persamaan?"]}'::jsonb, 'b', '["Sebelum menyusun persamaan, kita harus memahami informasi apa yang tersedia dan apa yang dicari."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m3-3', 'lesson:m3', 'm3', 'sedang', 'mcq', 'model', '"Umur ayah 3 kali umur anaknya." Jika a = umur ayah dan n = umur anak, persamaan yang tepat adalah ...', '{"options":[{"id":"a","text":"n = 3a"},{"id":"b","text":"a = 3n"},{"id":"c","text":"a + n = 3"},{"id":"d","text":"a − 3 = n"}],"context":null,"pairLabels":null,"hints":["Siapa yang umurnya lebih besar?"]}'::jsonb, 'b', '["Ayah lebih tua, jadi umur ayah = 3 × umur anak.","Ditulis a = 3n."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m3-4', 'lesson:m3', 'm3', 'sedang', 'tf', 'model', 'Pada soal "jumlah kaki ayam dan kambing adalah 56", persamaan yang tepat adalah a + k = 56.', '{"options":null,"context":null,"pairLabels":null,"hints":["Berapa kaki seekor ayam? Seekor kambing?"]}'::jsonb, 'false', '["a + k menyatakan banyak hewan, bukan banyak kaki.","Persamaan yang benar: 2a + 4k = 56."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m4-1', 'lesson:m4', 'm4', 'mudah', 'mcq', 'operasi', 'Sistem 3x + 2y = 16 dan 5x − 2y = 0. Agar y tereliminasi, kedua persamaan harus ...', '{"options":[{"id":"a","text":"Dijumlahkan"},{"id":"b","text":"Dikurangkan"},{"id":"c","text":"Dikalikan"},{"id":"d","text":"Dibagi"}],"context":null,"pairLabels":null,"hints":["Perhatikan tanda koefisien y."]}'::jsonb, 'a', '["Koefisien y adalah +2 dan −2 (berlawanan).","Jika dijumlahkan, 2y + (−2y) = 0 sehingga y hilang: 8x = 16."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m4-2', 'lesson:m4', 'm4', 'mudah', 'mcq', 'operasi', 'Sistem 4x + y = 11 dan 2x + y = 7. Agar y tereliminasi, kedua persamaan harus ...', '{"options":[{"id":"a","text":"Dijumlahkan"},{"id":"b","text":"Dikurangkan"},{"id":"c","text":"Dikalikan 2"},{"id":"d","text":"Tidak bisa dieliminasi"}],"context":null,"pairLabels":null,"hints":["Tanda koefisien y sama atau berbeda?"]}'::jsonb, 'b', '["Koefisien y sama-sama +1.","Dikurangkan: (4x + y) − (2x + y) = 11 − 7 → 2x = 4."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m4-3', 'lesson:m4', 'm4', 'mudah', 'tf', 'konsep', 'Mengalikan kedua ruas sebuah persamaan dengan bilangan yang sama (bukan nol) tidak mengubah penyelesaiannya.', '{"options":null,"context":null,"pairLabels":null,"hints":["Ingat analogi timbangan."]}'::jsonb, 'true', '["Persamaan tetap seimbang karena kedua ruas berubah dengan cara yang sama."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m4-4', 'lesson:m4', 'm4', 'sedang', 'number', 'langkah', 'Lengkapi hasil eliminasi y berikut: 2x = ...', '{"options":null,"context":["  x + y = 12","  x − y = 2","———————— +"," 2x     = ..."],"pairLabels":null,"hints":["Ruas kanan juga harus dijumlahkan."]}'::jsonb, '14', '["Ruas kanan dijumlahkan: 12 + 2 = 14.","Jadi 2x = 14 dan x = 7."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m5-1', 'lesson:m5', 'm5', 'sedang', 'number', 'langkah', 'Untuk mengeliminasi x dari 2x + y = 7 dan 3x + 2y = 12, persamaan pertama dikalikan 3, dan persamaan kedua dikalikan ...', '{"options":null,"context":null,"pairLabels":null,"hints":["Cari KPK dari 2 dan 3.","Bagi KPK dengan koefisien x pada persamaan kedua."]}'::jsonb, '2', '["KPK dari koefisien x (2 dan 3) adalah 6.","Persamaan kedua: 6 : 3 = 2."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m5-2', 'lesson:m5', 'm5', 'sedang', 'number', 'langkah', 'Lanjutkan proses berikut. Berapakah nilai y?', '{"options":null,"context":["  6x + 3y = 21","  6x + 4y = 24","———————— −","       −y = −3"],"pairLabels":null,"hints":["Jika −y = −3, maka y = ...?"]}'::jsonb, '3', '["Dari −y = −3, kalikan kedua ruas dengan −1.","y = 3."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m5-3', 'lesson:m5', 'm5', 'sedang', 'pair', 'penyelesaian', 'Tentukan penyelesaian dari x + 2y = 8 dan 3x − 2y = 8.', '{"options":null,"context":null,"pairLabels":null,"hints":["Koefisien y sudah berlawanan.","Jumlahkan kedua persamaan."]}'::jsonb, '4,2', '["Koefisien y berlawanan (+2 dan −2), jumlahkan: 4x = 16 → x = 4.","Substitusi: 4 + 2y = 8 → 2y = 4 → y = 2.","Periksa: 3(4) − 2(2) = 12 − 4 = 8 ✓"]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m5-4', 'lesson:m5', 'm5', 'mudah', 'mcq', 'langkah', 'Setelah koefisien salah satu variabel disamakan, langkah berikutnya adalah ...', '{"options":[{"id":"a","text":"Menjumlahkan atau mengurangkan kedua persamaan"},{"id":"b","text":"Menuliskan pasangan penyelesaian"},{"id":"c","text":"Mengalikan lagi dengan KPK"},{"id":"d","text":"Menggambar grafik"}],"context":null,"pairLabels":null,"hints":["Apa tujuan menyamakan koefisien?"]}'::jsonb, 'a', '["Koefisien yang sudah sama siap dihilangkan dengan penjumlahan atau pengurangan."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m6-1', 'lesson:m6', 'm6', 'mudah', 'tf', 'penyelesaian', 'Pasangan (5, 1) merupakan penyelesaian dari 2x − y = 9 dan x + y = 6.', '{"options":null,"context":null,"pairLabels":null,"hints":["Uji kedua persamaan."]}'::jsonb, 'true', '["2(5) − 1 = 9 ✓","5 + 1 = 6 ✓"]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m6-2', 'lesson:m6', 'm6', 'sedang', 'tf', 'penyelesaian', 'Pasangan (3, 4) merupakan penyelesaian dari x + y = 7 dan 2x − y = 3.', '{"options":null,"context":null,"pairLabels":null,"hints":["Jangan berhenti setelah persamaan pertama."]}'::jsonb, 'false', '["3 + 4 = 7 ✓","2(3) − 4 = 2 ≠ 3 ✗","Karena persamaan kedua tidak terpenuhi, pernyataan salah."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m6-3', 'lesson:m6', 'm6', 'sedang', 'mcq', 'langkah', 'Budi mengalikan persamaan x + 3y = 7 dengan 2 dan menulis 2x + 6y = 7. Apa kesalahannya?', '{"options":[{"id":"a","text":"Koefisien x seharusnya tetap 1"},{"id":"b","text":"Ruas kanan tidak ikut dikalikan; seharusnya 14"},{"id":"c","text":"Seharusnya dikalikan 3"},{"id":"d","text":"Tidak ada kesalahan"}],"context":null,"pairLabels":null,"hints":["Apakah semua suku sudah dikalikan 2?"]}'::jsonb, 'b', '["Semua suku harus dikalikan, termasuk ruas kanan: 7 × 2 = 14.","Hasil yang benar: 2x + 6y = 14."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m6-4', 'lesson:m6', 'm6', 'sedang', 'mcq', 'konsep', 'Hasil dari 5y − (−3y) adalah ...', '{"options":[{"id":"a","text":"2y"},{"id":"b","text":"−8y"},{"id":"c","text":"8y"},{"id":"d","text":"15y"}],"context":null,"pairLabels":null,"hints":["Minus dikali minus menjadi ...?"]}'::jsonb, 'c', '["Mengurangkan bilangan negatif sama dengan menjumlahkan: 5y − (−3y) = 5y + 3y = 8y."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m7-1', 'lesson:m7', 'm7', 'sedang', 'pair', 'cerita', 'Jumlah dua bilangan adalah 25 dan selisihnya 7. Tentukan bilangan besar dan bilangan kecil.', '{"options":null,"context":null,"pairLabels":["besar","kecil"],"hints":["Misalkan x bilangan besar, y bilangan kecil.","Koefisien y berlawanan, jumlahkan."]}'::jsonb, '16,9', '["Model: x + y = 25 dan x − y = 7.","Jumlahkan: 2x = 32 → x = 16.","y = 25 − 16 = 9. Periksa: 16 − 9 = 7 ✓"]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m7-2', 'lesson:m7', 'm7', 'sedang', 'number', 'cerita', 'Harga 2 kg gula dan 1 kg beras Rp40.000. Harga 1 kg gula dan 1 kg beras Rp26.000. Berapa rupiah harga 1 kg gula?', '{"options":null,"context":null,"pairLabels":null,"hints":["Koefisien b sama, kurangkan kedua persamaan."]}'::jsonb, '14000', '["Model: 2g + b = 40.000 dan g + b = 26.000.","Kurangkan: g = 14.000.","Periksa: b = 12.000; 2(14.000) + 12.000 = 40.000 ✓"]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m7-3', 'lesson:m7', 'm7', 'sulit', 'number', 'cerita', 'Di sebuah kandang terdapat 15 ekor ayam dan kambing. Jumlah kaki seluruhnya 40. Berapa ekor kambing?', '{"options":null,"context":null,"pairLabels":null,"hints":["Ayam berkaki 2, kambing berkaki 4.","Samakan koefisien a dengan mengalikan persamaan pertama dengan 2."]}'::jsonb, '5', '["Model: a + k = 15 dan 2a + 4k = 40.","Kalikan persamaan pertama dengan 2: 2a + 2k = 30.","Kurangkan: 2k = 10 → k = 5.","Periksa: a = 10; 2(10) + 4(5) = 40 ✓"]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('q-m7-4', 'lesson:m7', 'm7', 'sedang', 'mcq', 'cerita', 'Umur kakak 4 tahun lebih tua daripada umur adik. Jumlah umur mereka 20 tahun. Berapa umur kakak?', '{"options":[{"id":"a","text":"8 tahun"},{"id":"b","text":"10 tahun"},{"id":"c","text":"12 tahun"},{"id":"d","text":"16 tahun"}],"context":null,"pairLabels":null,"hints":["\"lebih tua 4 tahun\" berarti selisihnya 4."]}'::jsonb, 'c', '["Model: k − a = 4 dan k + a = 20.","Jumlahkan: 2k = 24 → k = 12.","Adik: 20 − 12 = 8. Periksa: 12 − 8 = 4 ✓"]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-m-01', 'practice:mudah', 'm1', 'mudah', 'mcq', 'konsep', 'Manakah yang merupakan persamaan linear dua variabel?', '{"options":[{"id":"a","text":"2x + 5 = 11"},{"id":"b","text":"x + 4y = 9"},{"id":"c","text":"x² − y = 3"},{"id":"d","text":"3xy = 12"}],"context":null,"pairLabels":null,"hints":["Hitung banyak variabel pada setiap pilihan.","Periksa pangkat variabelnya."]}'::jsonb, 'b', '["x + 4y = 9 memiliki dua variabel berpangkat satu.","Pilihan lain: satu variabel, ada pangkat dua, atau perkalian variabel."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-m-02', 'practice:mudah', 'm1', 'mudah', 'tf', 'konsep', 'Pada persamaan 4x + 3y = 24, konstantanya adalah 24.', '{"options":null,"context":null,"pairLabels":null,"hints":["Cari bilangan yang tidak menempel pada huruf."]}'::jsonb, 'true', '["Konstanta adalah suku tanpa variabel, yaitu 24."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-m-03', 'practice:mudah', 'm1', 'mudah', 'number', 'konsep', 'Berapakah koefisien x pada persamaan 6x − y = 10?', '{"options":null,"context":null,"pairLabels":null,"hints":["Koefisien adalah bilangan di depan variabel."]}'::jsonb, '6', '["Bilangan di depan x adalah 6."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-m-04', 'practice:mudah', 'm2', 'mudah', 'tf', 'penyelesaian', 'Pasangan (2, 5) adalah penyelesaian dari x + y = 7 dan y − x = 3.', '{"options":null,"context":null,"pairLabels":null,"hints":["Substitusikan x = 2 dan y = 5 ke kedua persamaan."]}'::jsonb, 'true', '["2 + 5 = 7 ✓","5 − 2 = 3 ✓","Kedua persamaan terpenuhi."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-m-05', 'practice:mudah', 'm2', 'mudah', 'mcq', 'penyelesaian', 'Pasangan (x, y) manakah yang memenuhi x + y = 10 dan x − y = 2?', '{"options":[{"id":"a","text":"(6, 4)"},{"id":"b","text":"(4, 6)"},{"id":"c","text":"(5, 5)"},{"id":"d","text":"(7, 3)"}],"context":null,"pairLabels":null,"hints":["Semua pilihan berjumlah 10. Cari yang selisihnya 2 dengan x lebih besar."]}'::jsonb, 'a', '["6 + 4 = 10 ✓ dan 6 − 4 = 2 ✓."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
