insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-m-07', 'practice:mudah', 'm4', 'mudah', 'mcq', 'operasi', 'Sistem 3x + 2y = 12 dan x + 2y = 8. Agar y tereliminasi, kedua persamaan ...', '{"options":[{"id":"a","text":"Dijumlahkan"},{"id":"b","text":"Dikurangkan"},{"id":"c","text":"Dikalikan 2"},{"id":"d","text":"Tidak dapat dieliminasi"}],"context":null,"pairLabels":null,"hints":["Jika tanda koefisien sama, apa operasinya?"]}'::jsonb, 'b', '["Koefisien y sama-sama +2, sehingga dikurangkan: 2x = 4 → x = 2."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
