insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-m-10', 'practice:mudah', 'm5', 'mudah', 'pair', 'penyelesaian', 'Tentukan penyelesaian dari x + y = 11 dan x − y = 5.', '{"options":null,"context":null,"pairLabels":null,"hints":["Koefisien y berlawanan.","Setelah dapat x, substitusikan ke x + y = 11."]}'::jsonb, '8,3', '["Jumlahkan: 2x = 16 → x = 8.","Substitusi: 8 + y = 11 → y = 3."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-m-11', 'practice:mudah', 'm5', 'mudah', 'pair', 'penyelesaian', 'Tentukan penyelesaian dari 2x + y = 10 dan x + y = 7.', '{"options":null,"context":null,"pairLabels":null,"hints":["Koefisien y sama-sama +1.","Kurangkan persamaan pertama dengan persamaan kedua."]}'::jsonb, '3,4', '["Kurangkan: (2x + y) − (x + y) = 10 − 7 → x = 3.","Substitusi: 3 + y = 7 → y = 4."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
