insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-m-13', 'practice:mudah', 'm3', 'mudah', 'mcq', 'model', 'Harga 1 buku dan 1 pensil Rp7.000. Harga 2 buku dan 1 pensil Rp12.000. Jika b = harga buku dan p = harga pensil, persamaan kedua adalah ...', '{"options":[{"id":"a","text":"2b + p = 12.000"},{"id":"b","text":"b + 2p = 12.000"},{"id":"c","text":"2b + p = 7.000"},{"id":"d","text":"2b × p = 12.000"}],"context":null,"pairLabels":null,"hints":["Banyak barang menjadi koefisien."]}'::jsonb, 'a', '["\"2 buku dan 1 pensil\" → 2b + p.","Harganya Rp12.000."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
