insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-s-01', 'practice:sedang', 'm5', 'sedang', 'number', 'langkah', 'Untuk mengeliminasi x dari 2x + 3y = 13 dan x + y = 5, persamaan kedua dikalikan ...', '{"options":null,"context":null,"pairLabels":null,"hints":["Koefisien x pada persamaan pertama adalah 2."]}'::jsonb, '2', '["Koefisien x adalah 2 dan 1.","Agar sama-sama 2, persamaan kedua dikali 2: 2x + 2y = 10."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-s-02', 'practice:sedang', 'm5', 'sedang', 'number', 'penyelesaian', 'Dari sistem 2x + 3y = 13 dan x + y = 5, berapakah nilai y?', '{"options":null,"context":null,"pairLabels":null,"hints":["Samakan dulu koefisien x.","Lalu kurangkan."]}'::jsonb, '3', '["Kalikan persamaan kedua dengan 2: 2x + 2y = 10.","Kurangkan: (2x + 3y) − (2x + 2y) = 13 − 10 → y = 3."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-s-03', 'practice:sedang', 'm5', 'sedang', 'pair', 'penyelesaian', 'Tentukan penyelesaian dari 3x + y = 11 dan x + 2y = 7.', '{"options":null,"context":null,"pairLabels":null,"hints":["Coba eliminasi y.","Kalikan persamaan pertama dengan 2."]}'::jsonb, '3,2', '["Eliminasi y: kalikan persamaan pertama dengan 2 → 6x + 2y = 22.","Kurangkan: 5x = 15 → x = 3.","Substitusi: 3(3) + y = 11 → y = 2."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-s-04', 'practice:sedang', 'm4', 'sedang', 'mcq', 'operasi', 'Sistem 2x + 3y = 12 dan 4x − 3y = 6. Agar y tereliminasi, kedua persamaan ...', '{"options":[{"id":"a","text":"Dijumlahkan"},{"id":"b","text":"Dikurangkan"},{"id":"c","text":"Persamaan pertama dikali 2 lalu dikurangkan"},{"id":"d","text":"Dibagi 3"}],"context":null,"pairLabels":null,"hints":["Koefisien y sudah sama besar. Bagaimana tandanya?"]}'::jsonb, 'a', '["Koefisien y adalah +3 dan −3 (berlawanan).","Dijumlahkan: 6x = 18 → x = 3."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-s-05', 'practice:sedang', 'm5', 'sedang', 'number', 'langkah', 'Lengkapi langkah eliminasi berikut: 3x = ...', '{"options":null,"context":["  4x + 2y = 20","   x + 2y = 11","———————— −","  3x      = ..."],"pairLabels":null,"hints":["Kurangkan ruas kanan."]}'::jsonb, '9', '["Ruas kanan dikurangkan: 20 − 11 = 9.","Jadi 3x = 9 dan x = 3."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-s-06', 'practice:sedang', 'm6', 'sedang', 'tf', 'penyelesaian', 'Pasangan (1, 4) adalah penyelesaian dari 3x + 2y = 11 dan 2x − y = −2.', '{"options":null,"context":null,"pairLabels":null,"hints":["Uji kedua persamaan dengan teliti, perhatikan tanda negatif."]}'::jsonb, 'true', '["3(1) + 2(4) = 3 + 8 = 11 ✓","2(1) − 4 = −2 ✓"]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-s-07', 'practice:sedang', 'm6', 'sedang', 'tf', 'penyelesaian', 'Pasangan (2, 3) adalah penyelesaian dari 4x − y = 5 dan x + 3y = 10.', '{"options":null,"context":null,"pairLabels":null,"hints":["Jangan hanya memeriksa persamaan pertama."]}'::jsonb, 'false', '["4(2) − 3 = 5 ✓","2 + 3(3) = 11 ≠ 10 ✗","Persamaan kedua tidak terpenuhi."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-s-08', 'practice:sedang', 'm5', 'sedang', 'mcq', 'langkah', 'Berapakah KPK dari koefisien x pada sistem 3x + 2y = 7 dan 4x − y = 2?', '{"options":[{"id":"a","text":"7"},{"id":"b","text":"12"},{"id":"c","text":"1"},{"id":"d","text":"24"}],"context":null,"pairLabels":null,"hints":["Kelipatan 3: 3, 6, 9, 12, ... Kelipatan 4: 4, 8, 12, ..."]}'::jsonb, 'b', '["Koefisien x adalah 3 dan 4.","KPK dari 3 dan 4 adalah 12."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-s-09', 'practice:sedang', 'm5', 'sedang', 'pair', 'penyelesaian', 'Tentukan penyelesaian dari 5x + 2y = 16 dan 3x − 2y = 0.', '{"options":null,"context":null,"pairLabels":null,"hints":["Koefisien y berlawanan."]}'::jsonb, '2,3', '["Jumlahkan: 8x = 16 → x = 2.","Substitusi: 5(2) + 2y = 16 → 2y = 6 → y = 3."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-s-10', 'practice:sedang', 'm7', 'sedang', 'number', 'cerita', 'Harga 2 pensil dan 1 penghapus Rp5.000. Harga 1 pensil dan 1 penghapus Rp3.500. Berapa rupiah harga 1 pensil?', '{"options":null,"context":null,"pairLabels":null,"hints":["Koefisien h sama, kurangkan."]}'::jsonb, '1500', '["Model: 2p + h = 5.000 dan p + h = 3.500.","Kurangkan: p = 1.500.","Periksa: h = 2.000; 2(1.500) + 2.000 = 5.000 ✓"]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-s-11', 'practice:sedang', 'm7', 'sedang', 'number', 'cerita', 'Di peternakan terdapat 25 ekor ayam dan kelinci. Jumlah kaki seluruhnya 70. Berapa ekor ayam?', '{"options":null,"context":null,"pairLabels":null,"hints":["Ayam berkaki 2, kelinci berkaki 4.","Hitung banyak kelinci dulu, lalu ayam."]}'::jsonb, '15', '["Model: a + k = 25 dan 2a + 4k = 70.","Kalikan persamaan pertama dengan 2: 2a + 2k = 50.","Kurangkan: 2k = 20 → k = 10.","a = 25 − 10 = 15."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-s-12', 'practice:sedang', 'm7', 'sedang', 'mcq', 'cerita', 'Umur ibu 3 kali umur Dina. Jumlah umur mereka 48 tahun. Berapa umur Dina?', '{"options":[{"id":"a","text":"12 tahun"},{"id":"b","text":"16 tahun"},{"id":"c","text":"24 tahun"},{"id":"d","text":"36 tahun"}],"context":null,"pairLabels":null,"hints":["Tulis i − 3d = 0 agar bentuknya ax + by = c."]}'::jsonb, 'a', '["Model: i = 3d (atau i − 3d = 0) dan i + d = 48.","Kurangkan: 4d = 48 → d = 12."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-s-13', 'practice:sedang', 'm5', 'sedang', 'mcq', 'langkah', 'Dari sistem x + 3y = 13 dan 2x − y = 5 diperoleh x = 4. Langkah berikutnya adalah ...', '{"options":[{"id":"a","text":"Menuliskan jawaban (4, 4)"},{"id":"b","text":"Mensubstitusikan x = 4 ke salah satu persamaan untuk mencari y"},{"id":"c","text":"Mengalikan kedua persamaan dengan 4"},{"id":"d","text":"Menjumlahkan x dan y"}],"context":null,"pairLabels":null,"hints":["Variabel apa yang belum diketahui?"]}'::jsonb, 'b', '["Nilai y dicari dengan substitusi: 4 + 3y = 13 → y = 3."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-s-14', 'practice:sedang', 'm6', 'sedang', 'number', 'langkah', 'Jika persamaan 2x − 3y = 4 dikalikan 3, berapakah konstanta di ruas kanan?', '{"options":null,"context":null,"pairLabels":null,"hints":["Ruas kanan juga ikut dikalikan."]}'::jsonb, '12', '["Semua suku dikali 3: 6x − 9y = 12."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-h-01', 'practice:sulit', 'm5', 'sulit', 'pair', 'penyelesaian', 'Tentukan penyelesaian dari 3x + 4y = 18 dan 2x + 3y = 13.', '{"options":null,"context":null,"pairLabels":null,"hints":["KPK koefisien x adalah 6.","Kedua persamaan perlu dikalikan."]}'::jsonb, '2,3', '["Eliminasi x: (1) × 2 → 6x + 8y = 36; (2) × 3 → 6x + 9y = 39.","Kurangkan: y = 3.","Substitusi: 3x + 12 = 18 → x = 2."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-h-02', 'practice:sulit', 'm5', 'sulit', 'pair', 'penyelesaian', 'Tentukan penyelesaian dari 4x − 3y = 1 dan 3x + 2y = 22.', '{"options":null,"context":null,"pairLabels":null,"hints":["KPK koefisien y (3 dan 2) adalah 6.","Tanda koefisien y berlawanan setelah dikalikan."]}'::jsonb, '4,5', '["Eliminasi y: (1) × 2 → 8x − 6y = 2; (2) × 3 → 9x + 6y = 66.","Jumlahkan: 17x = 68 → x = 4.","Substitusi: 3(4) + 2y = 22 → y = 5."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-h-03', 'practice:sulit', 'm5', 'sulit', 'number', 'penyelesaian', 'Dari sistem 5x + 2y = 4 dan 3x − 4y = 18, berapakah nilai y?', '{"options":null,"context":null,"pairLabels":null,"hints":["Hasilnya bisa negatif.","Hati-hati: 6y − (−20y) = 26y."]}'::jsonb, '-3', '["Eliminasi x: (1) × 3 → 15x + 6y = 12; (2) × 5 → 15x − 20y = 90.","Kurangkan: 26y = −78 → y = −3.","Periksa: x = 2; 5(2) + 2(−3) = 4 ✓"]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-h-04', 'practice:sulit', 'm5', 'sulit', 'mcq', 'operasi', 'Untuk mengeliminasi y dari 3x + 4y = 10 dan 5x − 6y = 4 dengan pengali terkecil, langkah yang tepat adalah ...', '{"options":[{"id":"a","text":"Persamaan (1) × 3 dan (2) × 2, lalu dijumlahkan"},{"id":"b","text":"Persamaan (1) × 3 dan (2) × 2, lalu dikurangkan"},{"id":"c","text":"Persamaan (1) × 6 dan (2) × 4, lalu dikurangkan"},{"id":"d","text":"Persamaan (1) × 2 dan (2) × 3, lalu dijumlahkan"}],"context":null,"pairLabels":null,"hints":["Cari KPK dari 4 dan 6.","Setelah dikali, bandingkan tandanya."]}'::jsonb, 'a', '["KPK dari 4 dan 6 adalah 12: 12 : 4 = 3 dan 12 : 6 = 2.","Hasilnya +12y dan −12y (berlawanan), sehingga dijumlahkan."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-h-05', 'practice:sulit', 'm5', 'sulit', 'number', 'langkah', 'Lengkapi langkah eliminasi berikut: 19x = ...', '{"options":null,"context":["   9x + 12y = 30","  10x − 12y = 8","————————— +","  19x       = ..."],"pairLabels":null,"hints":["Jumlahkan ruas kanan."]}'::jsonb, '38', '["Ruas kanan dijumlahkan: 30 + 8 = 38.","x = 38 : 19 = 2."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-h-06', 'practice:sulit', 'm2', 'sulit', 'tf', 'konsep', 'Sistem 2x + 4y = 10 dan x + 2y = 5 memiliki tepat satu penyelesaian.', '{"options":null,"context":null,"pairLabels":null,"hints":["Bandingkan kedua persamaan. Apakah salah satunya kelipatan yang lain?"]}'::jsonb, 'false', '["Persamaan pertama adalah 2 kali persamaan kedua (berimpit).","Kedua garis sama persis, sehingga penyelesaiannya tak hingga."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-h-07', 'practice:sulit', 'm2', 'sulit', 'mcq', 'konsep', 'Sistem x + 2y = 6 dan 2x + 4y = 8 memiliki ...', '{"options":[{"id":"a","text":"Tepat satu penyelesaian"},{"id":"b","text":"Tidak ada penyelesaian"},{"id":"c","text":"Tak hingga penyelesaian"},{"id":"d","text":"Dua penyelesaian"}],"context":null,"pairLabels":null,"hints":["Kalikan persamaan pertama dengan 2 lalu bandingkan."]}'::jsonb, 'b', '["Kalikan persamaan pertama dengan 2: 2x + 4y = 12.","Ruas kiri sama tetapi ruas kanan berbeda (12 ≠ 8): garis sejajar, tidak ada penyelesaian."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-h-08', 'practice:sulit', 'm7', 'sulit', 'number', 'cerita', 'Harga 2 tiket dewasa dan 3 tiket anak Rp70.000. Harga 3 tiket dewasa dan 1 tiket anak Rp70.000. Berapa rupiah harga 1 tiket anak?', '{"options":null,"context":null,"pairLabels":null,"hints":["Eliminasi a dengan mengalikan persamaan kedua dengan 3."]}'::jsonb, '10000', '["Model: 2d + 3a = 70.000 dan 3d + a = 70.000.","Kalikan persamaan kedua dengan 3: 9d + 3a = 210.000.","Kurangkan: 7d = 140.000 → d = 20.000.","Substitusi: 3(20.000) + a = 70.000 → a = 10.000."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-h-09', 'practice:sulit', 'm7', 'sulit', 'number', 'cerita', 'Harga 4 kg apel dan 3 kg jeruk Rp99.000. Harga 2 kg apel dan 5 kg jeruk Rp95.000. Berapa rupiah harga 1 kg jeruk?', '{"options":null,"context":null,"pairLabels":null,"hints":["Samakan koefisien a."]}'::jsonb, '13000', '["Model: 4a + 3j = 99.000 dan 2a + 5j = 95.000.","Kalikan persamaan kedua dengan 2: 4a + 10j = 190.000.","Kurangkan: 7j = 91.000 → j = 13.000.","Periksa: a = 15.000; 2(15.000) + 5(13.000) = 95.000 ✓"]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-h-10', 'practice:sulit', 'm7', 'sulit', 'number', 'cerita', 'Enam tahun yang lalu, umur ayah 4 kali umur anaknya. Sekarang jumlah umur keduanya 62 tahun. Berapa umur anak sekarang?', '{"options":null,"context":null,"pairLabels":null,"hints":["Umur enam tahun lalu adalah (umur sekarang − 6).","Sederhanakan a − 6 = 4(n − 6) terlebih dahulu."]}'::jsonb, '16', '["Misalkan a = umur ayah sekarang, n = umur anak sekarang.","Enam tahun lalu: a − 6 = 4(n − 6) → a − 4n = −18.","Jumlah sekarang: a + n = 62.","Kurangkan: (a + n) − (a − 4n) = 62 − (−18) → 5n = 80 → n = 16."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-h-11', 'practice:sulit', 'm7', 'sulit', 'pair', 'cerita', 'Di tempat parkir terdapat 40 kendaraan berupa motor dan mobil. Jumlah rodanya 110. Tentukan banyak motor dan banyak mobil.', '{"options":null,"context":null,"pairLabels":["motor","mobil"],"hints":["Motor 2 roda, mobil 4 roda."]}'::jsonb, '25,15', '["Model: m + c = 40 dan 2m + 4c = 110.","Kalikan persamaan pertama dengan 2: 2m + 2c = 80.","Kurangkan: 2c = 30 → c = 15.","m = 40 − 15 = 25."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-h-12', 'practice:sulit', 'm4', 'sulit', 'tf', 'operasi', 'Pada sistem 3x − 2y = 5 dan 4x − 2y = 6, variabel y dihilangkan dengan menjumlahkan kedua persamaan.', '{"options":null,"context":null,"pairLabels":null,"hints":["Tanda kedua koefisien y sama atau berbeda?"]}'::jsonb, 'false', '["Koefisien y sama-sama −2 (tanda sama).","Jika dijumlahkan menjadi −4y. Seharusnya dikurangkan: −2y − (−2y) = 0."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-h-13', 'practice:sulit', 'm6', 'sulit', 'mcq', 'langkah', 'Sistem 2x + y = 7 dan x − y = 2. Doni menjumlahkan kedua persamaan dan menulis 3x = 5. Bagaimana perbaikannya?', '{"options":[{"id":"a","text":"Ruas kanan seharusnya 7 + 2 = 9, sehingga x = 3"},{"id":"b","text":"Seharusnya dikurangkan, sehingga x = 5"},{"id":"c","text":"Ruas kiri seharusnya 2x, sehingga x = 2,5"},{"id":"d","text":"Tidak ada kesalahan, x = 5/3"}],"context":null,"pairLabels":null,"hints":["Periksa penjumlahan ruas kanan."]}'::jsonb, 'a', '["Ruas kanan juga dijumlahkan: 7 + 2 = 9.","3x = 9 → x = 3, lalu y = 3 − 2 = 1."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('p-h-14', 'practice:sulit', 'm5', 'sulit', 'number', 'langkah', 'Diketahui 3x + 2y = 7 dan 2x + 3y = 8. Berapakah nilai x + y? (Petunjuk: ada cara cepat!)', '{"options":null,"context":null,"pairLabels":null,"hints":["Coba jumlahkan kedua persamaan.","Perhatikan bahwa koefisiennya menjadi sama."]}'::jsonb, '3', '["Jumlahkan kedua persamaan: 5x + 5y = 15.","Bagi dengan 5: x + y = 3.","(Memang x = 1 dan y = 2.)"]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e01', 'evaluation', 'm1', 'mudah', 'mcq', 'konsep', 'Bentuk umum persamaan linear dua variabel adalah ...', '{"options":[{"id":"a","text":"ax + by = c"},{"id":"b","text":"ax² + by = c"},{"id":"c","text":"ax + b = c"},{"id":"d","text":"axy = c"}],"context":null,"pairLabels":null,"hints":null}'::jsonb, 'a', '["PLDV memuat dua variabel berpangkat satu: ax + by = c."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e02', 'evaluation', 'm1', 'mudah', 'number', 'konsep', 'Berapakah konstanta pada persamaan 9p − 4q = 27?', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, '27', '["Konstanta adalah suku tanpa variabel, yaitu 27."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e03', 'evaluation', 'm1', 'mudah', 'tf', 'konsep', 'Persamaan 2x + 3 = 9 termasuk persamaan linear dua variabel.', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, 'false', '["Persamaan tersebut hanya memiliki satu variabel (x)."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e04', 'evaluation', 'm1', 'sedang', 'number', 'penyelesaian', 'Jika (3, y) merupakan penyelesaian dari 4x − y = 7, berapakah nilai y?', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, '5', '["4(3) − y = 7 → 12 − y = 7 → y = 5."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e05', 'evaluation', 'm2', 'mudah', 'mcq', 'konsep', 'Penyelesaian SPLDV adalah pasangan nilai yang ...', '{"options":[{"id":"a","text":"Memenuhi persamaan pertama saja"},{"id":"b","text":"Memenuhi persamaan kedua saja"},{"id":"c","text":"Memenuhi kedua persamaan sekaligus"},{"id":"d","text":"Tidak memenuhi kedua persamaan"}],"context":null,"pairLabels":null,"hints":null}'::jsonb, 'c', '["Penyelesaian SPLDV harus membuat kedua persamaan benar secara bersamaan."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e06', 'evaluation', 'm2', 'sedang', 'tf', 'penyelesaian', 'Pasangan (4, 1) merupakan penyelesaian dari x + 2y = 6 dan 3x − y = 11.', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, 'true', '["4 + 2(1) = 6 ✓","3(4) − 1 = 11 ✓"]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e07', 'evaluation', 'm2', 'sedang', 'mcq', 'konsep', 'Grafik dua persamaan dalam sebuah SPLDV berpotongan di titik (2, −1). Penyelesaian SPLDV tersebut adalah ...', '{"options":[{"id":"a","text":"x = −1 dan y = 2"},{"id":"b","text":"x = 2 dan y = −1"},{"id":"c","text":"x = 2 dan y = 1"},{"id":"d","text":"Tidak dapat ditentukan"}],"context":null,"pairLabels":null,"hints":null}'::jsonb, 'b', '["Koordinat titik potong (x, y) = (2, −1) adalah penyelesaiannya."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e08', 'evaluation', 'm2', 'sulit', 'mcq', 'konsep', 'Sistem 3x − y = 4 dan 6x − 2y = 8 memiliki ...', '{"options":[{"id":"a","text":"Tepat satu penyelesaian"},{"id":"b","text":"Tidak ada penyelesaian"},{"id":"c","text":"Tak hingga penyelesaian"},{"id":"d","text":"Tepat dua penyelesaian"}],"context":null,"pairLabels":null,"hints":null}'::jsonb, 'c', '["Persamaan kedua adalah 2 × persamaan pertama, sehingga kedua garis berimpit.","Penyelesaiannya tak hingga."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e09', 'evaluation', 'm3', 'mudah', 'mcq', 'model', '"Selisih dua bilangan adalah 8" dengan x bilangan yang lebih besar dan y bilangan yang lebih kecil ditulis ...', '{"options":[{"id":"a","text":"x + y = 8"},{"id":"b","text":"x − y = 8"},{"id":"c","text":"y − x = 8"},{"id":"d","text":"xy = 8"}],"context":null,"pairLabels":null,"hints":null}'::jsonb, 'b', '["Selisih = bilangan besar − bilangan kecil: x − y = 8."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e10', 'evaluation', 'm3', 'sedang', 'mcq', 'model', 'Harga 2 kg beras dan 3 kg telur Rp105.000. Harga 1 kg beras dan 2 kg telur Rp65.000. Jika b = harga 1 kg beras dan t = harga 1 kg telur, modelnya adalah ...', '{"options":[{"id":"a","text":"2b + 3t = 65.000 dan b + 2t = 105.000"},{"id":"b","text":"3b + 2t = 105.000 dan 2b + t = 65.000"},{"id":"c","text":"2b + 3t = 105.000 dan b + 2t = 65.000"},{"id":"d","text":"2b + 3t = 105.000 dan 2b + t = 65.000"}],"context":null,"pairLabels":null,"hints":null}'::jsonb, 'c', '["2 kg beras dan 3 kg telur → 2b + 3t = 105.000.","1 kg beras dan 2 kg telur → b + 2t = 65.000."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e11', 'evaluation', 'm3', 'sedang', 'tf', 'model', '"Jumlah roda s sepeda (2 roda) dan b becak (3 roda) adalah 48" dapat ditulis 2s + 3b = 48.', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, 'true', '["Roda sepeda: 2s; roda becak: 3b; jumlahnya 48."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e12', 'evaluation', 'm3', 'sulit', 'mcq', 'model', 'Umur ayah sekarang 4 kali umur anaknya. Lima tahun lagi, umur ayah menjadi 3 kali umur anaknya. Jika a = umur ayah dan n = umur anak sekarang, persamaan untuk kalimat kedua adalah ...', '{"options":[{"id":"a","text":"a + 5 = 3(n + 5)"},{"id":"b","text":"a + 5 = 3n"},{"id":"c","text":"a = 3(n + 5)"},{"id":"d","text":"a − 5 = 3(n − 5)"}],"context":null,"pairLabels":null,"hints":null}'::jsonb, 'a', '["Lima tahun lagi umur ayah a + 5 dan umur anak n + 5.","Maka a + 5 = 3(n + 5)."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e13', 'evaluation', 'm4', 'mudah', 'mcq', 'konsep', 'Tujuan utama metode eliminasi adalah ...', '{"options":[{"id":"a","text":"Menambah banyak variabel"},{"id":"b","text":"Menghilangkan salah satu variabel"},{"id":"c","text":"Menggambar grafik"},{"id":"d","text":"Mengubah persamaan menjadi pertidaksamaan"}],"context":null,"pairLabels":null,"hints":null}'::jsonb, 'b', '["Eliminasi berarti menghilangkan salah satu variabel agar tersisa persamaan satu variabel."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e14', 'evaluation', 'm4', 'sedang', 'mcq', 'operasi', 'Sistem 5x + 3y = 21 dan 2x + 3y = 12. Agar y tereliminasi, kedua persamaan ...', '{"options":[{"id":"a","text":"Dijumlahkan"},{"id":"b","text":"Dikurangkan"},{"id":"c","text":"Dikalikan 3"},{"id":"d","text":"Dibagi 3"}],"context":null,"pairLabels":null,"hints":null}'::jsonb, 'b', '["Koefisien y sama-sama +3, jadi dikurangkan: 3x = 9 → x = 3."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e15', 'evaluation', 'm4', 'mudah', 'tf', 'operasi', 'Jika koefisien suatu variabel bernilai sama tetapi berlawanan tanda, kedua persamaan dijumlahkan untuk mengeliminasinya.', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, 'true', '["Contoh: +2y + (−2y) = 0, sehingga variabel y hilang."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e16', 'evaluation', 'm5', 'sedang', 'number', 'langkah', 'Untuk mengeliminasi y dari 2x + 3y = 9 dan 5x − y = 14, persamaan kedua dikalikan ...', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, '3', '["Koefisien y: 3 dan −1. Agar menjadi 3 dan −3, persamaan kedua dikali 3."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e17', 'evaluation', 'm5', 'sedang', 'number', 'penyelesaian', 'Dari sistem 2x + 3y = 9 dan 5x − y = 14, berapakah nilai x?', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, '3', '["Persamaan kedua × 3: 15x − 3y = 42.","Jumlahkan dengan persamaan pertama: 17x = 51 → x = 3."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e18', 'evaluation', 'm5', 'sedang', 'pair', 'penyelesaian', 'Tentukan penyelesaian dari x + 3y = 10 dan 2x − y = 6.', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, '4,2', '["Persamaan pertama × 2: 2x + 6y = 20.","Kurangkan dengan 2x − y = 6: 7y = 14 → y = 2.","Substitusi: x + 6 = 10 → x = 4."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e19', 'evaluation', 'm5', 'sulit', 'pair', 'penyelesaian', 'Tentukan penyelesaian dari 3x + 5y = 1 dan 2x + 3y = 0.', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, '-3,2', '["Eliminasi x: (1) × 2 → 6x + 10y = 2; (2) × 3 → 6x + 9y = 0.","Kurangkan: y = 2.","Substitusi: 2x + 6 = 0 → x = −3."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e20', 'evaluation', 'm5', 'sulit', 'number', 'penyelesaian', 'Dari sistem 4x + 3y = 23 dan 6x − 5y = −13, berapakah nilai x?', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, '2', '["Eliminasi y: (1) × 5 → 20x + 15y = 115; (2) × 3 → 18x − 15y = −39.","Jumlahkan: 38x = 76 → x = 2."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e21', 'evaluation', 'm6', 'mudah', 'tf', 'penyelesaian', 'Pasangan (3, 2) merupakan penyelesaian dari 2x + y = 8 dan x − y = 1.', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, 'true', '["2(3) + 2 = 8 ✓","3 − 2 = 1 ✓"]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e22', 'evaluation', 'm6', 'sedang', 'tf', 'penyelesaian', 'Pasangan (2, 4) merupakan penyelesaian dari 3x − y = 2 dan x + 2y = 9.', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, 'false', '["3(2) − 4 = 2 ✓","2 + 2(4) = 10 ≠ 9 ✗"]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e23', 'evaluation', 'm6', 'sedang', 'mcq', 'konsep', 'Untuk memastikan penyelesaian SPLDV benar, nilai x dan y disubstitusikan ke ...', '{"options":[{"id":"a","text":"Persamaan pertama saja"},{"id":"b","text":"Persamaan hasil eliminasi saja"},{"id":"c","text":"Kedua persamaan awal"},{"id":"d","text":"Tidak perlu disubstitusikan"}],"context":null,"pairLabels":null,"hints":null}'::jsonb, 'c', '["Penyelesaian harus memenuhi kedua persamaan awal."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e24', 'evaluation', 'm6', 'sulit', 'mcq', 'langkah', 'Hasil dari (−4y) − (−7y) adalah ...', '{"options":[{"id":"a","text":"−11y"},{"id":"b","text":"3y"},{"id":"c","text":"−3y"},{"id":"d","text":"11y"}],"context":null,"pairLabels":null,"hints":null}'::jsonb, 'b', '["−4y − (−7y) = −4y + 7y = 3y."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e25', 'evaluation', 'm7', 'sedang', 'number', 'cerita', 'Harga 3 buku dan 2 pulpen Rp23.000. Harga 2 buku dan 2 pulpen Rp18.000. Berapa rupiah harga 1 buku?', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, '5000', '["Kurangkan: (3b + 2p) − (2b + 2p) = 23.000 − 18.000 → b = 5.000."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e26', 'evaluation', 'm7', 'sedang', 'number', 'cerita', 'Jumlah kelereng Andi dan Budi 45 butir. Kelereng Andi 9 butir lebih banyak daripada kelereng Budi. Berapa butir kelereng Andi?', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, '27', '["Model: a + b = 45 dan a − b = 9.","Jumlahkan: 2a = 54 → a = 27."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e27', 'evaluation', 'm7', 'sulit', 'number', 'cerita', 'Berat 2 karung pupuk A dan 3 karung pupuk B adalah 130 kg. Berat 3 karung pupuk A dan 2 karung pupuk B adalah 120 kg. Berapa kg berat 1 karung pupuk A?', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, '20', '["Model: 2a + 3b = 130 dan 3a + 2b = 120.","Eliminasi b: (1) × 2 → 4a + 6b = 260; (2) × 3 → 9a + 6b = 360.","Kurangkan: 5a = 100 → a = 20."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e28', 'evaluation', 'm7', 'sulit', 'number', 'cerita', 'Uang Rp50.000 terdiri atas 13 lembar pecahan Rp2.000 dan Rp5.000. Berapa lembar pecahan Rp5.000?', '{"options":null,"context":null,"pairLabels":null,"hints":null}'::jsonb, '8', '["Model: d + l = 13 dan 2.000d + 5.000l = 50.000 (disederhanakan: 2d + 5l = 50).","Persamaan pertama × 2: 2d + 2l = 26.","Kurangkan: 3l = 24 → l = 8."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e29', 'evaluation', 'm7', 'sulit', 'pair', 'cerita', 'Jumlah umur kakak dan adik 30 tahun. Dua kali umur kakak dikurangi umur adik sama dengan 24 tahun. Tentukan umur kakak dan adik.', '{"options":null,"context":null,"pairLabels":["kakak","adik"],"hints":null}'::jsonb, '18,12', '["Model: k + a = 30 dan 2k − a = 24.","Jumlahkan: 3k = 54 → k = 18.","a = 30 − 18 = 12."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, topic, difficulty, type, format, prompt, payload, answer, explanation) values ('e30', 'evaluation', 'm4', 'sulit', 'mcq', 'operasi', 'Pada sistem 2x + 5y = 1 dan 3x + 2y = 7, langkah yang tepat untuk mengeliminasi x adalah ...', '{"options":[{"id":"a","text":"(1) × 3 dan (2) × 2, lalu dikurangkan"},{"id":"b","text":"(1) × 3 dan (2) × 2, lalu dijumlahkan"},{"id":"c","text":"(1) × 2 dan (2) × 3, lalu dikurangkan"},{"id":"d","text":"(1) × 5 dan (2) × 2, lalu dikurangkan"}],"context":null,"pairLabels":null,"hints":null}'::jsonb, 'a', '["KPK dari 2 dan 3 adalah 6: (1) × 3 → 6x + 15y = 3; (2) × 2 → 6x + 4y = 14.","Tanda koefisien x sama, sehingga dikurangkan: 11y = −11 → y = −1."]'::jsonb) on conflict (id) do update set prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation;
